// Observabilidad M2: registra qué Worker se invocó, con qué parámetros y qué devolvió.
// Evolución del log del M1: ahora audita la delegación Manager → Workers.
const leer = (n) => {
  try { return $(n).isExecuted ? ($(n).first()?.json ?? null) : null; }
  catch (e) { return null; }
};

const _ns = $('Normalizar Sesión').first().json;
const trigger = { sessionId: _ns.session_id, chatInput: _ns.user_message };
const router = leer('Agente IA')?.output ?? null;

const cAnalista = leer('Contrato · W1 Analista');
const rAnalista = leer('Ejecutar · W1 Analista') ?? leer('Contingencia · W1');

const cRedactor = leer('Contrato · W2 LEAD') ?? leer('Contrato · W2 POSTVENTA') ?? leer('Contrato · W2 ESCAPE HUMANO');
const rRedactor = leer('Ejecutar · W2 Redactor') ?? leer('Contingencia · W2');

const invocaciones = [];
if (cAnalista) invocaciones.push({ worker: 'W1 · Analista de Leads', parametros: cAnalista, respuesta: rAnalista ?? { status: 'sin_respuesta' } });
if (cRedactor) invocaciones.push({ worker: 'W2 · Redactor de Notificaciones', parametros: cRedactor, respuesta: rRedactor ?? { status: 'sin_respuesta' } });

const envioOk = rRedactor?.status === 'success';
const escapeGenerico = !router
  || router.confianza < 0.6
  || router.intencion === 'INDETERMINADO'
  || rAnalista?.status === 'error';

let ruta;
if (!router) ruta = 'ESCAPE_HUMANO (falló el agente)';
else if (router.confianza < 0.6) ruta = `ESCAPE_HUMANO (confianza ${router.confianza})`;
else if (rAnalista?.status === 'error') ruta = 'COTIZACION → ESCAPE_HUMANO (cayó W1)';
else ruta = router.intencion;

// Si el Analista detectó que falta teléfono o email, no se promete contacto: primero hay que pedirlo.
const faltantes = Array.isArray(rAnalista?.data?.faltantes) ? rAnalista.data.faltantes : [];
const faltaContacto = faltantes.some((f) => /tel[eé]fono|email|contacto/i.test(String(f)));

let respuesta;
if (escapeGenerico) {
  respuesta = envioOk
    ? 'Gracias por escribirnos. Tu consulta quedó registrada y un asesor se va a comunicar con vos a la brevedad.'
    : 'Gracias por escribirnos. En este momento no pudimos registrar tu consulta, ¿nos escribís de nuevo en unos minutos?';
} else if (envioOk && !faltaContacto) {
  // Solo se confirma la derivación cuando el asesor ya tiene cómo contactar a la persona.
  respuesta = `${router.respuesta_cliente} Tu consulta ya quedó en manos de un asesor, que se va a comunicar con vos a la brevedad.`;
} else {
  respuesta = router.respuesta_cliente;
}

const fmt = (o) => JSON.stringify(o, null, 2).split('\n').join('\n   ');
const lineas = [
  'REPORTE DE TRAZABILIDAD - CHECKPOINT 4',
  '======================================',
  'Workflow: ' + $workflow.name,
  'Ejecución: ' + $execution.id,
  'Fecha: ' + new Date().toISOString(),
  'Sesión: ' + trigger.sessionId,
  '',
  'Mensaje del usuario: ' + trigger.chatInput,
  '',
  '--- CLASIFICACIÓN DEL MANAGER ---',
  router
    ? `Intención: ${router.intencion} | Confianza: ${router.confianza} | Ramo: ${router.ramo}`
    : 'El agente no pudo clasificar el mensaje: se activó la vía de escape.',
  'Ruta tomada: ' + ruta,
  '',
  `--- WORKERS INVOCADOS (${invocaciones.length}) ---`,
];

if (invocaciones.length === 0) {
  lineas.push('Ninguno: el Manager resolvió la consulta sin delegar.', '');
}
invocaciones.forEach((inv, k) => {
  lineas.push(`${k + 1}. ${inv.worker}`);
  lineas.push('   Parámetros enviados: ' + fmt(inv.parametros));
  lineas.push('   Respuesta devuelta: ' + fmt(inv.respuesta));
  lineas.push('');
});

lineas.push('--- RESPUESTA FINAL AL CLIENTE ---', respuesta);

return [{
  json: {
    ejecucion_id: $execution.id,
    workflow: $workflow.name,
    fecha: new Date().toISOString(),
    ruta,
    workers_invocados: invocaciones.map((x) => x.worker),
    cantidad_workers: invocaciones.length,
    respuesta_final: respuesta,
    reporte: lineas.join('\n'),
  },
}];

// Acumulador de turno: arma el material del resumen SIN volcar nada crudo.
const leer = (n) => { try { return $(n).isExecuted ? ($(n).first()?.json ?? null) : null; } catch (e) { return null; } };

const ctx = leer('Contexto · Usuario Recurrente') ?? leer('Contexto · Usuario Nuevo') ?? {};
const log = $('Formatear log de observabilidad').first().json;
const router = leer('Agente IA')?.output ?? null;

const contador = Number(ctx.contador_previo ?? 0) + 1;

// Estado del caso derivado de la ruta real que tomó el Manager.
const ruta = String(log.ruta ?? '');
let estado;
if (ruta.startsWith('ESCAPE_HUMANO') || ruta.includes('ATENCION_HUMANA')) estado = 'DERIVADO_ASESOR';
else if (ruta.includes('POSTVENTA')) estado = 'DERIVADO_ASESOR';
else if (ruta.includes('COTIZACION')) estado = log.cantidad_workers >= 2 ? 'DERIVADO_ASESOR' : 'ESPERANDO_DATOS';
else estado = 'EN_CALIFICACION';

const RAMOS = ['Automotor','Hogar / Combinado Familiar','Vida','Accidentes Personales','Comercio / Integral','ART'];
const ramo = RAMOS.includes(router?.ramo) ? router.ramo : 'Sin definir';

// Material para el resumidor: resumen previo + turno actual. Nunca el historial crudo.
const historial = [
  'RESUMEN PREVIO: ' + (ctx.last_summary ?? 'sin resumen previo'),
  'DATOS DUROS PREVIOS: ' + (ctx.datos_clave ?? 'ninguno'),
  'ESTADO PREVIO: ' + (ctx.estado_caso ?? 'NUEVO'),
  'ACCION PENDIENTE PREVIA: ' + (ctx.accion_pendiente ?? 'ninguna'),
  '',
  '--- TURNO ACTUAL (intercambio ' + contador + ') ---',
  'Cliente dijo: ' + (ctx.user_message ?? ''),
  'Asistente respondió: ' + (log.respuesta_final ?? ''),
  router ? ('Clasificación: ' + router.intencion + ' | ramo ' + router.ramo + ' | confianza ' + router.confianza) : 'Clasificación: no disponible',
  router ? ('Datos que dejó: ' + JSON.stringify(router.datos ?? {})) : '',
  'Ruta del sistema: ' + ruta,
].filter(Boolean).join('\n');

return [{ json: {
  session_id: ctx.session_id ?? $('Normalizar Sesión').first().json.session_id,
  record_id: ctx.record_id ?? '',
  tipo_contacto: ctx.tipo_contacto ?? 'NUEVO',
  nombre_usuario: (router?.datos?.nombre || ctx.user_name === 'todavía no se presentó' ? (router?.datos?.nombre ?? '') : ctx.user_name) || '',
  contador_mensajes: contador,
  supera_umbral: contador > 5,
  estado_caso: estado,
  ramo,
  historial_compacto: historial,
  // fallback para la rama corta: resumen mínimo sin gastar tokens
  resumen_liviano: (ctx.tipo_contacto === 'RECURRENTE' && ctx.last_summary !== 'no quedó resumen de la charla anterior')
      ? ctx.last_summary
      : 'Contacto en curso por ' + ramo + '. Todavía no superó los 5 intercambios: sin resumen consolidado.',
  accion_liviana: ctx.accion_pendiente && ctx.accion_pendiente !== 'ninguna' ? ctx.accion_pendiente : 'Continuar la calificación en el próximo mensaje',
}}];

// Cerrojo anti-ruido: ninguna transcripción, HTML o log entra a la base.
const t = $('Acumulador de Turno').first().json;
const raw = $json.output ?? $json;

const limpiar = (s, max) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')                          // etiquetas HTML
  .replace(/https?:\/\/\S+/g, '')                    // URLs
  .replace(/\b(at\s+\w+\.|Error:|ECONNREFUSED|stack|Traceback)\b.*/gi, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

let asunto = limpiar(raw.asunto_principal, 400);
let accion = limpiar(raw.accion_requerida, 200);
let puntos = Array.isArray(raw.puntos_clave) ? raw.puntos_clave : [];
puntos = puntos.map((p) => limpiar(p, 120)).filter(Boolean).slice(0, 8);

// Si el modelo falló o devolvió basura, cae al resumen liviano en vez de ensuciar la base.
const sospechoso = !asunto || asunto.length < 15 || /\{|\}|\[object|undefined/.test(asunto);
if (sospechoso) {
  asunto = t.resumen_liviano;
  accion = t.accion_liviana;
  puntos = [];
}

return [{ json: {
  session_id: t.session_id,
  nombre_usuario: t.nombre_usuario,
  estado_caso: t.estado_caso,
  ramo: t.ramo,
  contador_mensajes: t.contador_mensajes,
  resumen_consolidado: asunto,
  datos_clave: JSON.stringify(puntos),
  accion_requerida: accion || 'Sin acción pendiente',
  degradado: sospechoso,
}}];
